#include<bits/stdc++.h>
using namespace std;

int main(){
	int n;
	cin >> n;
	set<int>s;
	for(int i=0;i<n;i++){
		int ai;
		cin >> ai;
		s.insert(ai);
	}

	long long ans=0;
	int pos=0;
	for(int i=0;i<n;i++){
		auto it=s.lower_bound(pos);
		int nxt;
		if(it==s.begin()){
			nxt=*it;
		}else if(it==s.end()){
			nxt=*--it;
		}else{
			int cand1=*it;
			int cand2=*--it;
			if(abs(cand1-pos)<abs(cand2-pos)){
				nxt=cand1;
			}else{
				nxt=cand2;
			}
		}
		ans+=abs(nxt-pos);
		s.erase(nxt);
		pos=nxt;
	}
	cout << ans << endl;
}
N=int(input())
A=list(map(int,input().split()))

N+=1
A.append(0)
A.sort()
P=A.index(0)
L=P-1
R=P+1
ans=0

pos=0
for _ in range(N-1):
  if L==-1:
    ans+=A[R]-pos
    pos=A[R]
    R+=1
  elif R==N:
    ans+=pos-A[L]
    pos=A[L]
    L-=1
  else:
    if pos-A[L]<=A[R]-pos:
      ans+=pos-A[L]
      pos=A[L]
      L-=1
    else:
      ans+=A[R]-pos
      pos=A[R]
      R+=1

print(ans)
